INSERT INTO question (category, title, answer_standard, key_points, difficulty, source) VALUES
('Java 基础', 'String、StringBuilder、StringBuffer 的区别？', 'String 是不可变对象，每次拼接都会生成新对象；StringBuilder 可变、非线程安全、单线程下性能最好；StringBuffer 可变、通过 synchronized 保证线程安全、性能略低。', '["String 不可变","StringBuilder 非线程安全","StringBuffer 加锁"]', 1, '面试归纳'),
('Java 基础', '== 和 equals 的区别？', '== 比较基本类型的值，或引用类型的地址；equals 默认等价于 ==，但 String 等类重写后比较内容。重写 equals 必须同时重写 hashCode。', '["== 比引用","equals 可重写比内容","重写要同步 hashCode"]', 1, '面试归纳'),
('Java 基础', 'HashMap 的底层原理？', '底层是数组加链表加红黑树。对 key 做哈希后定位桶，冲突用链表；链表长度达到 8 且数组长度达到 64 时转为红黑树，扩容时容量翻倍并重新散列。', '["数组+链表+红黑树","扩容翻倍","树化阈值 8"]', 3, '面试归纳'),
('Java 基础', 'ConcurrentHashMap 如何保证线程安全？', 'JDK8 用 CAS 加 synchronized 锁桶头节点实现细粒度并发；JDK7 是分段锁。相比 Hashtable 全表加锁，并发度更高。', '["CAS","synchronized 锁桶","对比 Hashtable"]', 3, '面试归纳'),
('Java 基础', 'ArrayList 和 LinkedList 的区别？', 'ArrayList 底层是动态数组，随机访问 O(1)，尾部增删快；LinkedList 底层是双向链表，随机访问 O(n)，头尾插入删除快。', '["底层结构不同","随机访问复杂度","适用场景"]', 1, '面试归纳'),
('Java 基础', '线程有哪几种状态？', '共六种：NEW、RUNNABLE、BLOCKED、WAITING、TIMED_WAITING、TERMINATED。BLOCKED 等锁，WAITING 无限期等待，TIMED_WAITING 限时等待。', '["六种状态","BLOCKED 与 WAITING 区别","wait 与 sleep"]', 2, '面试归纳'),
('数据库', '索引为什么用 B+ 树而不是 B 树？', 'B+ 树只在叶子节点存数据，非叶子节点只存索引键，同样大小的页能放更多键，扇出更大、树更矮、磁盘 IO 更少；叶子节点用链表相连，利于范围查询。', '["非叶子不存数据扇出更大","树更矮 IO 更少","叶子链表利于范围查询"]', 2, '面试归纳'),
('数据库', '聚簇索引和非聚簇索引的区别？', 'InnoDB 中聚簇索引叶子节点存整行数据；二级索引叶子节点存主键值，查到后还要回表取整行。覆盖索引可以避免回表。', '["叶子存整行 vs 主键","回表","覆盖索引"]', 2, '面试归纳'),
('数据库', '事务的 ACID 是什么？', '原子性：要么全成功要么全失败；一致性：事务前后数据满足约束；隔离性：并发事务互不干扰；持久性：提交后不丢失。', '["ACID 含义","各自实现机制","隔离级别"]', 1, '面试归纳'),
('数据库', '事务隔离级别有哪些？', '读未提交、读已提交、可重复读、串行化，分别解决脏读、不可重复读、幻读。MySQL 默认可重复读，通过 MVCC 加间隙锁解决大部分幻读。', '["四种隔离级别","脏读不可重复读幻读","MySQL 默认 RR"]', 3, '面试归纳'),
('数据库', '什么是覆盖索引？', '查询需要的列全部包含在索引里，直接从索引取数，不用回表，explain 会显示 Using index，能显著减少 IO。', '["覆盖索引定义","不回表","explain 验证"]', 2, '面试归纳'),
('数据库', '一条 SQL 在 MySQL 里是怎么执行的？', '连接器建立连接并鉴权，分析器做词法语法分析，优化器选索引和连接顺序，执行器调用存储引擎接口逐行执行并返回结果。', '["Server 层与引擎层","优化器选索引","执行器调用引擎"]', 3, '面试归纳'),
('框架', 'Spring 的 IoC 是什么？', '控制反转，把对象的创建和依赖关系交给容器管理，通过构造器或字段注入，降低耦合，便于测试。', '["控制反转","依赖注入","Bean 容器"]', 1, '面试归纳'),
('框架', 'Spring AOP 的原理和使用场景？', '基于动态代理：有接口用 JDK 动态代理，无接口用 CGLIB。把日志、事务、权限等横切逻辑从业务代码中抽离。', '["动态代理","JDK vs CGLIB","日志事务场景"]', 2, '面试归纳'),
('框架', 'Spring 事务失效的常见场景？', '类内部自调用绕过代理、方法非 public、异常被 try-catch 吞掉、抛的是非运行时异常且未声明回滚、传播行为配置不当。', '["自调用失效","异常类型","传播行为"]', 3, '面试归纳'),
('框架', 'Spring Bean 的生命周期？', '实例化、属性填充、执行 Aware 接口、前置后置处理器、初始化方法、使用、销毁方法，容器关闭时回调。', '["实例化","Aware 与后置处理器","初始化与销毁"]', 3, '面试归纳'),
('框架', 'SpringBoot 自动配置原理？', '@SpringBootApplication 包含 @EnableAutoConfiguration，启动时根据 AutoConfiguration.imports 加载配置类，配合 @Conditional 条件注解按需生效。', '["@EnableAutoConfiguration","条件注解","starter 机制"]', 2, '面试归纳'),
('框架', '@Autowired 和 @Resource 的区别？', '@Autowired 是 Spring 提供的，默认按类型注入，可配合 @Qualifier；@Resource 是 JDK 的，默认按名称注入。', '["按类型 vs 按名称","提供方不同","@Qualifier 配合"]', 1, '面试归纳'),
('项目', '介绍一下你的电影观影网站项目。', '先一句话说清业务，再说技术栈（前后端分离、数据库），最后讲自己负责的模块和最有价值的产出。', '["业务背景","技术栈","个人职责与产出"]', 2, '面试归纳'),
('项目', '项目里如何做登录认证？', '用户提交账号密码，后端校验后生成会话凭证（Session 或 JWT），密码用加盐哈希存储，拦截器或过滤器校验凭证。', '["认证方式","密码加密存储","拦截校验"]', 2, '面试归纳'),
('项目', '如何保证接口性能？', '先定位慢查询，加合适的索引；热点数据用缓存；列表做分页；避免 N+1 查询；必要时异步化。', '["慢查询与索引","缓存","分页与避免 N+1"]', 2, '面试归纳'),
('项目', '项目中遇到过什么难题，怎么解决的？', '按问题现象、定位过程、方案取舍、结果验证四步讲：先复现，再缩小范围，对比几个方案的代价后选择，最后用数据证明有效。', '["问题定位","方案取舍","结果验证"]', 3, '面试归纳'),
('项目', '项目为什么用 MySQL 而不是别的存储？', '数据是强关系型且需要事务一致性，MySQL 生态成熟、运维简单；非结构化或高吞吐场景才考虑 Redis、MongoDB 等。', '["关系型与事务","生态成熟","选型对比"]', 1, '面试归纳'),
('项目', '你的项目是怎么部署的？', '本地打包成 jar，推到服务器用 Docker 跑，数据库用容器或云实例，配置走环境变量，日志落到文件便于排错。', '["构建与部署","环境变量隔离配置","日志与监控"]', 1, '面试归纳');